@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun EditExerciseScreen(
    exerciseId: Int,
    onNavigateBack: () -> Unit,
    viewModel: EditExerciseViewModel = hiltViewModel()
) {
    val uiState by viewModel.uiState.collectAsStateWithLifecycle()
    val isDarkTheme = isSystemInDarkTheme()

    val name by viewModel.name.collectAsStateWithLifecycle()
    val description by viewModel.description.collectAsStateWithLifecycle()
    val instructions by viewModel.instructions.collectAsStateWithLifecycle()
    val selectedExerciseType by viewModel.selectedExerciseType.collectAsStateWithLifecycle()
    val selectedDifficulty by viewModel.selectedDifficulty.collectAsStateWithLifecycle()
    val selectedDays by viewModel.selectedDays.collectAsStateWithLifecycle()
    val photoUri by viewModel.photoUri.collectAsStateWithLifecycle()
    val photoTaken by viewModel.photoTaken.collectAsStateWithLifecycle()

    val backgroundColor = if (isDarkTheme) Color(0xFF0F172A) else Color(0xFFF8FAFC)
    val textColor = if (isDarkTheme) Color.White else Color(0xFF0F172A)
    val labelColor = if (isDarkTheme) Color(0xFF94A3B8) else Color(0xFF64748B)
    val textFieldBackground = if (isDarkTheme) Color(0xFF1E293B) else Color.White
    val textFieldBorder = if (isDarkTheme) Color(0xFF334155) else Color(0xFFE2E8F0)
    val placeholderColor = if (isDarkTheme) Color(0xFF64748B) else Color(0xFF94A3B8)

    val exerciseTypes = listOf("CARDIO", "FUERZA", "ESTIRAMIENTO", "AEROBICOS", "YOGA", "LEVANTAMIENTO DE PESAS", "PLIOMETRIA")
    val difficultyOptions = listOf("Facil", "Medio", "Dificil")
    val daysOfWeek = listOf("Lunes", "Martes", "Miercoles", "Jueves", "Viernes", "Sabado", "Domingo")

    val takePictureLauncher = rememberLauncherForActivityResult(
        contract = ActivityResultContracts.TakePicture()
    ) { success: Boolean ->
        viewModel.onPhotoTaken(success)
    }

    val cameraPermissionLauncher = rememberLauncherForActivityResult(
        contract = ActivityResultContracts.RequestPermission()
    ) { isGranted: Boolean ->
        if (isGranted) {
            val uri = viewModel.createPhotoUri()
            takePictureLauncher.launch(uri)
        }
    }

    val galleryLauncher = rememberLauncherForActivityResult(
        contract = ActivityResultContracts.GetContent()
    ) { uri ->
        uri?.let { viewModel.onGalleryImageSelected(it) }
    }

    LaunchedEffect(exerciseId) {
        viewModel.loadExercise(exerciseId)
    }

    LaunchedEffect(uiState.exerciseUpdated) {
        if (uiState.exerciseUpdated) {
            viewModel.resetExerciseUpdated()
            onNavigateBack()
        }
    }

    Scaffold(
        modifier = Modifier.fillMaxSize(),
        containerColor = backgroundColor,
        topBar = {
            TopAppBar(
                title = {
                    Text(
                        text = "Editar Ejercicio",
                        fontWeight = FontWeight.Bold,
                        fontSize = 20.sp,
                        color = textColor
                    )
                },
                navigationIcon = {
                    IconButton(onClick = onNavigateBack) {
                        Icon(
                            imageVector = Icons.AutoMirrored.Filled.ArrowBack,
                            contentDescription = "Back",
                            tint = labelColor
                        )
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(containerColor = backgroundColor)
            )
        }
    ) { innerPadding ->
        Box(
            modifier = Modifier
                .fillMaxSize()
                .padding(innerPadding)
        ) {
            when {
                uiState.isLoading && uiState.exercise == null -> {
                    CircularProgressIndicator(
                        modifier = Modifier.align(Alignment.Center),
                        color = Color(0xFF10B981)
                    )
                }

                uiState.exercise == null -> {
                    Column(
                        modifier = Modifier
                            .align(Alignment.Center)
                            .padding(24.dp),
                        horizontalAlignment = Alignment.CenterHorizontally,
                        verticalArrangement = Arrangement.spacedBy(12.dp)
                    ) {
                        Text(
                            text = "Ejercicio no encontrado",
                            fontWeight = FontWeight.SemiBold,
                            color = textColor
                        )
                        Button(
                            onClick = onNavigateBack,
                            colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF10B981))
                        ) {
                            Text("Volver", color = Color.White)
                        }
                    }
                }

                else -> {
                    Column(
                        modifier = Modifier
                            .fillMaxSize()
                            .verticalScroll(rememberScrollState())
                            .padding(16.dp)
                            .padding(bottom = 80.dp),
                        verticalArrangement = Arrangement.spacedBy(24.dp)
                    ) {
                        Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                            Text(
                                text = "FOTO DEL EJERCICIO (OPCIONAL)",
                                fontSize = 12.sp,
                                fontWeight = FontWeight.Bold,
                                color = labelColor,
                                letterSpacing = 1.2.sp,
                                modifier = Modifier.padding(start = 4.dp)
                            )

                            Box(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .height(200.dp)
                                    .clip(RoundedCornerShape(12.dp))
                                    .border(
                                        width = 1.dp,
                                        color = if (photoTaken || !uiState.exercise?.gifUrl.isNullOrBlank()) {
                                            Color(0xFF10B981)
                                        } else {
                                            textFieldBorder
                                        },
                                        shape = RoundedCornerShape(12.dp)
                                    ),
                                contentAlignment = Alignment.Center
                            ) {
                                val previewModel = photoUri ?: uiState.exercise?.gifUrl
                                if (previewModel != null) {
                                    AsyncImage(
                                        model = ImageRequest.Builder(LocalContext.current)
                                            .data(previewModel)
                                            .crossfade(true)
                                            .build(),
                                        contentDescription = "Foto del ejercicio",
                                        modifier = Modifier
                                            .fillMaxSize()
                                            .clip(RoundedCornerShape(12.dp)),
                                        contentScale = ContentScale.Crop
                                    )

                                    Row(
                                        modifier = Modifier
                                            .align(Alignment.TopEnd)
                                            .padding(8.dp),
                                        horizontalArrangement = Arrangement.spacedBy(4.dp)
                                    ) {
                                        EditExerciseSmallIconButton(
                                            icon = Icons.Default.PhotoCamera,
                                            onClick = { cameraPermissionLauncher.launch(Manifest.permission.CAMERA) }
                                        )
                                        EditExerciseSmallIconButton(
                                            icon = Icons.Default.PhotoLibrary,
                                            onClick = { galleryLauncher.launch("image/*") }
                                        )
                                    }
                                } else {
                                    Row(
                                        horizontalArrangement = Arrangement.spacedBy(24.dp),
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Column(
                                            horizontalAlignment = Alignment.CenterHorizontally,
                                            verticalArrangement = Arrangement.spacedBy(6.dp),
                                            modifier = Modifier.clickable {
                                                cameraPermissionLauncher.launch(Manifest.permission.CAMERA)
                                            }
                                        ) {
                                            Icon(
                                                imageVector = Icons.Default.PhotoCamera,
                                                contentDescription = "Tomar foto",
                                                tint = labelColor,
                                                modifier = Modifier.size(36.dp)
                                            )
                                            Text(text = "Camara", fontSize = 12.sp, color = placeholderColor)
                                        }

                                        Box(
                                            modifier = Modifier
                                                .width(1.dp)
                                                .height(48.dp)
                                                .background(textFieldBorder)
                                        )

                                        Column(
                                            horizontalAlignment = Alignment.CenterHorizontally,
                                            verticalArrangement = Arrangement.spacedBy(6.dp),
                                            modifier = Modifier.clickable {
                                                galleryLauncher.launch("image/*")
                                            }
                                        ) {
                                            Icon(
                                                imageVector = Icons.Default.PhotoLibrary,
                                                contentDescription = "Elegir de galeria",
                                                tint = labelColor,
                                                modifier = Modifier.size(36.dp)
                                            )
                                            Text(text = "Galeria", fontSize = 12.sp, color = placeholderColor)
                                        }
                                    }
                                }
                            }
                        }

                        Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                            Text(
                                text = "NOMBRE DEL EJERCICIO",
                                fontSize = 12.sp,
                                fontWeight = FontWeight.Bold,
                                color = labelColor,
                                letterSpacing = 1.2.sp,
                                modifier = Modifier.padding(start = 4.dp)
                            )
                            InputFitness(
                                value = name,
                                onValueChange = viewModel::onNameChange,
                                placeholder = "e.g. Sentadillas con barra"
                            )
                        }

                        Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                            Text(
                                text = "TIPO DE EJERCICIO (OPCIONAL)",
                                fontSize = 12.sp,
                                fontWeight = FontWeight.Bold,
                                color = labelColor,
                                letterSpacing = 1.2.sp,
                                modifier = Modifier.padding(start = 4.dp)
                            )
                            exerciseTypes.forEach { option ->
                                Row(
                                    verticalAlignment = Alignment.CenterVertically,
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .clickable {
                                            viewModel.onExerciseTypeChange(
                                                if (selectedExerciseType == option) null else option
                                            )
                                        }
                                ) {
                                    RadioButton(
                                        selected = selectedExerciseType == option,
                                        onClick = {
                                            viewModel.onExerciseTypeChange(
                                                if (selectedExerciseType == option) null else option
                                            )
                                        },
                                        colors = RadioButtonDefaults.colors(
                                            selectedColor = Color(0xFF10B981),
                                            unselectedColor = labelColor
                                        )
                                    )
                                    Text(text = option, fontSize = 14.sp, color = textColor)
                                }
                            }
                        }

                        Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                            Text(
                                text = "DIFICULTAD",
                                fontSize = 12.sp,
                                fontWeight = FontWeight.Bold,
                                color = labelColor,
                                letterSpacing = 1.2.sp,
                                modifier = Modifier.padding(start = 4.dp)
                            )
                            difficultyOptions.forEach { option ->
                                Row(
                                    verticalAlignment = Alignment.CenterVertically,
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .clickable { viewModel.onDifficultyChange(option) }
                                ) {
                                    RadioButton(
                                        selected = selectedDifficulty == option,
                                        onClick = { viewModel.onDifficultyChange(option) },
                                        colors = RadioButtonDefaults.colors(
                                            selectedColor = Color(0xFF10B981),
                                            unselectedColor = labelColor
                                        )
                                    )
                                    Text(text = option, fontSize = 14.sp, color = textColor)
                                }
                            }
                        }

                        Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                            Text(
                                text = "DIAS PROGRAMADOS (OPCIONAL)",
                                fontSize = 12.sp,
                                fontWeight = FontWeight.Bold,
                                color = labelColor,
                                letterSpacing = 1.2.sp,
                                modifier = Modifier.padding(start = 4.dp)
                            )
                            daysOfWeek.forEach { day ->
                                Row(
                                    verticalAlignment = Alignment.CenterVertically,
                                    modifier = Modifier.fillMaxWidth()
                                ) {
                                    Checkbox(
                                        checked = selectedDays.contains(day),
                                        onCheckedChange = { viewModel.onDayToggle(day) },
                                        colors = CheckboxDefaults.colors(
                                            checkedColor = Color(0xFF10B981),
                                            uncheckedColor = labelColor
                                        )
                                    )
                                    Text(text = day, fontSize = 14.sp, color = textColor)
                                }
                            }
                        }

                        Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                            Text(
                                text = "DESCRIPCION",
                                fontSize = 12.sp,
                                fontWeight = FontWeight.Bold,
                                color = labelColor,
                                letterSpacing = 1.2.sp,
                                modifier = Modifier.padding(start = 4.dp)
                            )
                            OutlinedTextField(
                                value = description,
                                onValueChange = viewModel::onDescriptionChange,
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .height(120.dp),
                                placeholder = {
                                    Text(
                                        text = "Describe el ejercicio...",
                                        color = placeholderColor,
                                        fontSize = 16.sp
                                    )
                                },
                                shape = RoundedCornerShape(12.dp),
                                colors = OutlinedTextFieldDefaults.colors(
                                    focusedContainerColor = textFieldBackground,
                                    unfocusedContainerColor = textFieldBackground,
                                    focusedBorderColor = Color(0xFF10B981),
                                    unfocusedBorderColor = textFieldBorder,
                                    focusedTextColor = textColor,
                                    unfocusedTextColor = textColor,
                                    cursorColor = Color(0xFF10B981)
                                )
                            )
                        }

                        Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                            Text(
                                text = "INSTRUCCIONES (OPCIONAL)",
                                fontSize = 12.sp,
                                fontWeight = FontWeight.Bold,
                                color = labelColor,
                                letterSpacing = 1.2.sp,
                                modifier = Modifier.padding(start = 4.dp)
                            )
                            OutlinedTextField(
                                value = instructions,
                                onValueChange = viewModel::onInstructionsChange,
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .height(180.dp),
                                placeholder = {
                                    Text(
                                        text = "1. Posicion inicial...\n2. Ejecutar movimiento...\n3. Volver a posicion...",
                                        color = placeholderColor,
                                        fontSize = 16.sp
                                    )
                                },
                                shape = RoundedCornerShape(12.dp),
                                colors = OutlinedTextFieldDefaults.colors(
                                    focusedContainerColor = textFieldBackground,
                                    unfocusedContainerColor = textFieldBackground,
                                    focusedBorderColor = Color(0xFF10B981),
                                    unfocusedBorderColor = textFieldBorder,
                                    focusedTextColor = textColor,
                                    unfocusedTextColor = textColor,
                                    cursorColor = Color(0xFF10B981)
                                )
                            )
                        }

                        if (uiState.errorMessage != null) {
                            Card(
                                modifier = Modifier.fillMaxWidth(),
                                colors = CardDefaults.cardColors(
                                    containerColor = Color(0xFF991B1B).copy(alpha = 0.1f)
                                ),
                                shape = RoundedCornerShape(12.dp)
                            ) {
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(16.dp),
                                    horizontalArrangement = Arrangement.spacedBy(12.dp),
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Icon(
                                        imageVector = Icons.Default.Warning,
                                        contentDescription = null,
                                        tint = Color(0xFFEF4444)
                                    )
                                    Text(
                                        text = uiState.errorMessage.orEmpty(),
                                        color = Color(0xFFEF4444),
                                        fontSize = 14.sp
                                    )
                                }
                            }
                        }

                        Button(
                            onClick = { viewModel.updateExercise(exerciseId) },
                            modifier = Modifier
                                .fillMaxWidth()
                                .height(56.dp),
                            enabled = !uiState.isLoading && name.isNotBlank() && description.isNotBlank(),
                            shape = RoundedCornerShape(12.dp),
                            colors = ButtonDefaults.buttonColors(
                                containerColor = Color(0xFF10B981),
                                disabledContainerColor = Color(0xFF10B981).copy(alpha = 0.5f)
                            )
                        ) {
                            if (uiState.isLoading) {
                                CircularProgressIndicator(
                                    modifier = Modifier.height(24.dp),
                                    color = Color.White,
                                    strokeWidth = 2.dp
                                )
                            } else {
                                Row(
                                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Icon(
                                        imageVector = Icons.Default.Check,
                                        contentDescription = null,
                                        tint = Color.White
                                    )
                                    Text(
                                        text = "Actualizar Ejercicio",
                                        fontSize = 16.sp,
                                        fontWeight = FontWeight.SemiBold,
                                        color = Color.White
                                    )
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

